/* 110 年疼痛專科歷屆考題。請保留原始題號與官方答案；醫學驗證另行記錄。 */
window.PAIN_EXAM_SEEDS=(window.PAIN_EXAM_SEEDS||[]).concat([{"id":"official-110-1","year":110,"number":1,"topic":"未分類","text":"Which of the following statement concerning “postoperative pain” is least likely?","options":["Management of postoperative pain is challenging.","Management of postoperative pain is based on current understanding of the peripheral and central mechanisms involved in nociceptive transmission.","Chronic pain after surgery is an underdiagnosed condition","Advances in understanding the genetic profile of patients should help improve treatment of postoperative pain.","It is not essential that the neuronal response to surgery be blocked to achieve the task of optimal pain control."],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":1,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-2","year":110,"number":2,"topic":"未分類","text":"下列幾項關於疼痛名詞的定義或說明，依照 Bonica’s Management of Pain 5th ed 或疼痛學 理，哪一項是錯誤？","options":["Anesthesia dolorosa: Spontaneous pain in an area or region that is anesthetic","Catastrophizing: A cognitive and emotional process which can be an important predictor of negative response to both acute and chronic pain","Chronic widespread pain includes nonradicular back pain, fibromyalgia, irritable bowel syndrome, pelvic pain, tension-type headache, and temporomandibular disorders (TMD).","Conditioned pain modulation: a mechanism can be assessed by measuring tonic pain response after a conditioned phasic pain stimulus","Hyperpathia: A painful syndrome characterized by an abnormally painful reaction to a stimulus"],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"(考題出處：Bonica's Management of Pain Fifth Edition; Chap 2, page 229-231; (D) Conditioned pain modulation: a mechanism can be assessed by measuring “phasic” pain response after a conditioned “tonic” pain stimulus)","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":1,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-3","year":110,"number":3,"topic":"未分類","text":"Which of the following statement concerning “muscle pain” is least likely?","options":["Muscle pain is distinct from cutaneous pain.","Muscle pain is one of the most common pain complaints.","Muscle nociceptors are free nerve endings that are connected to the central nervous system.","Most nociceptors cannot be excited by algesic agents, including bradykinin, serotonin.","In damaged muscle, the nociceptors have a lowered mechanical threshold."],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":1,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-4","year":110,"number":4,"topic":"未分類","text":"Which of the following diagnostic tests that aid in the diagnosis of complex regional pain syndrome?","options":["Bone scintigraphy","Plain radiography and X-ray bone densitometry","Quantitative sensory testing","Skin temperature measurement","All of above"],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":2,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-5","year":110,"number":5,"topic":"未分類","text":"Which of the following is the acceptable statement about pathogenesis of FMS?","options":["There is evidence to suggest that FMS is a disorder of abnormal processing of sensory information within the central nervous system.","Several neurochemical mediators of pain, substance P, nerve growth factor, dynorphin A, glutamate, nitric oxide, serotonin and noradrenaline are viewed as pronociceptive because they carry or amplify afferent signals, leading to the brain perception of increased pain.","The elevation of cerebrospinal fluid substance P in FMS is due to lowered activity of cerebrospinal fluid substance P esterase because the rate of cleavage of libeled substance P by FMS cerebrospinal fluid was lower than normal.","In different subtypes of FMS, it is believed that nerve growth factor may be responsible for the elevated cerebrospinal fluid substance P through its effects on central sensitization and neuroplasticity.","A specific Gi-protein–coupled receptor in peripheral blood leukocytes was found to be dysfunctional in patients with FMS. This resulted in lower baseline, also depressed intracellular levels of cyclic AMP and proposed as a diagnostic test for FMS."],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":2,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-6","year":110,"number":6,"topic":"未分類","text":"Which drug below is less likely an option for inhibiting central sensitization following acute postoperative pain:","options":["NMDA antagonist","Opioid","COX2-inhibitor","Pre-emptive analgesia","Gabapentin"],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":2,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-7","year":110,"number":7,"topic":"未分類","text":"A 61-year-old woman presents to the pain clinic with a chief complaint of left shoulder and arm pain 3 years after undergoing radiation therapy for breast cancer. Physical examination reveals lymphedema of the left axilla with noticeable skin changes. Examination of the left supraclavicular area precipitates a sharp pain that radiates down her left arm. Which of the following is her likely diagnosis?","options":["Tumor metastasis","Cervical radiculopathy","Reflex sympathetic dystrophy","Thrombangitis obliterans","Radiation-induced plexopathy"],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":3,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-8","year":110,"number":8,"topic":"未分類","text":"Which of the following is not true about post-mastectomy pain?","options":["Mastectomy may result in chronic pain in as many as half of those patients.","This pain often starts immediately or a few days postoperatively.","This pain is usually neuropathic in character.","It is suspected that the intercostobrachial nerve is often damaged during axillary node dissection","The incidence of phantom breast syndrome 1 year after surgery is less than 5%."],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":3,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-9","year":110,"number":9,"topic":"未分類","text":"According to the long-form McGill Pain Questionnaire (MPQ) pain rating index scores, which of the following acute pain status is rated the highest pain score?","options":["Amputation of digit","Labor pain","Abdominal gynecological surgery","Fracture.","Lower abdominal surgery (males)"],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":3,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-10","year":110,"number":10,"topic":"未分類","text":"Which of the following symptom is not often seen in patients with physical dependence (abstinence syndrome -(withdrawal) ) ?","options":["abdominal cramps","constipationn","vomiting","pupil dilatation","sweating"],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":3,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-11","year":110,"number":11,"topic":"未分類","text":"About chemical neurolytic nerve blocks, which one of following statements is wrong?","options":["Phenol or ethanol is usually used for chemical denervation.","The duration of these blocks is often disappointingly brief.","They may induce deafferentation-neuropathic type pain.","They are often indicated for patients with chronic pain and a normal life expectancy.","They can be used in patients with advanced cancer disease."],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":4,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-12","year":110,"number":12,"topic":"未分類","text":"Which of the following combination of lesion site with referral site describing pain referral is not common in cancer patients suffering from cancer pain?","options":["(Diaphragmatic irritation) and (Shoulder)","(Urothelial tract) and (Inguinal region and genitalia)","(C7–T1 vertebrae) and (Interscapular)","(L1–2) and (Sacroiliac joint and hip)","all of the above are common found in patients with cancre pain"],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處： Chapter 73 –Cancer Pain Assessment and Syndromes / Table 73-1, page 1040","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":4,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-13","year":110,"number":13,"topic":"未分類","text":"About image-guided lumbar sympathetic block, which the following indication is not proper?","options":["Sympathetically maintained pain","Reflex sympathetic dystrophy","Phantom low limb pain","Raynaud’s disease","Chronic pancreatitis"],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：P511-512","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":4,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-14","year":110,"number":14,"topic":"未分類","text":"Which one of the following statement about the pathophysiology of herpes zoster is wrong?","options":["Herpes zoster most commonly manifests in the distribution of a single dorsal sensory or cranial nerve ganglion.","Why the reactivation of virus occurs in one ganglion when latent virus is present throughout the patient’s sensory ganglia is clear.","Declining cellular immunity is a major risk factor for reactivation of the virus, which is thought to occur when cell-mediated immunity falls below a critical level.","This impression is supported by evidence that even individuals with adequate levels of serum antibodies to varicella-zoster virus (VZV) antigen can, over time, exhibit T cells with reduced ability to proliferate and defend against VZV infections.","Cell-mediated immunity appears to play a crucial role in preventing reactivation of latent VZV."],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：Bonica's Management of Pain, 5e, p. 375.","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":5,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-15","year":110,"number":15,"topic":"未分類","text":"關於 cordotomy 的敘述，下列何者錯誤？ Ablation 目標是 spinothalamic tract","options":["Indication 是 bilateral 的 pelvic、flank、chest wall pain","因為 opioids treatment 的進步以及 intrathecal pain pump 的發展，cordotomy 的施行比以 前減少","手術方式通常是在 C1/2 level 經皮施行","手術也可在 mid-to-upper thoracic level（T4）施行",""],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"(P.1700)","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":5,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-16","year":110,"number":16,"topic":"未分類","text":"Which of the following cell type sense the initial “endanger signal” and participates in the initial phase of pathogenesis of the nerve injury induced neuropathic pain?","options":["Microglia","Spinal lamina I and II neuron","Astrocyte","oligodendrocyte",""],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"P73-76","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":5,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-17","year":110,"number":17,"topic":"未分類","text":"Which of the following description about spinal cord plasticity and pain is incorrect?","options":["Some spinal nociceptive neurons receive convergent input from high- and low- threshold sensory fibers thus called wide–dynamic range neurons","Glutamate is the major fast excitatory neurotransmitter in all nociceptive afferent nerve fibers. Glutamate can bind to three types of ionotropic glutamate receptors and to G protein–coupled metabotropic glutamate receptors to modify neuroexcitability.","Hyperalgesia and allodynia can even be induced in humans in the absence of any sensory stimuli, such as during prolonged application of opioids or on abrupt withdrawal of opioids..","Spinal nociception is under powerful control from descending inhibitory and facilitatory pathways. Under normal conditions, descending facilitation appears to prevail over inhibitory pathway.",""],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"P95-102","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":5,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-18","year":110,"number":18,"topic":"未分類","text":"About epidural steroid injection, which one of following statements is wrong?","options":["Spinal stenosis is an indication for epidural steroid..","Do not use for non-specific low back pain.","Do not repeat more than three times per year.","May cause pain from chronic arachnoiditis.","Efficacy is less with radicular pain that has lasted longer than 3 months."],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：Textbook of Pain, Chapter 33, p517","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":6,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-19","year":110,"number":19,"topic":"未分類","text":"Pain is a frequent consequence of spinal cord injury (SCI). Which of the following statement is least likely:","options":["Below-level neuropathic pain is most likely described as severe or excruciating months or years following initial injury.","Damage to the spinothalamic tracts is an important ingredient in the development of neuropathic pain following SCI.","Chronic musculoskeletal pain is common in tetraplegic patients after SCI.","Patients with cervical SCI are at risk of developing CRPS affecting upper limbs.","Below-level neuropathic pain is also referred to deafferentation pain."],"officialAnswer":"C","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：P.1043~1047","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":6,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-20","year":110,"number":20,"topic":"未分類","text":"下列有關常用疼痛評估量表的敘述何者正確?","options":["常用的疼痛強度量表是 Visual analogue scale, 是用 0 分到 10 讓病患挑選","Leeds Assessment of Neuropathic Symptoms and Signs (LANSS) 用以偵測 neuropathic 的 好處是方便病患自己選答","DN4 雖然項目不多, 但需要 clinician 執行 examination","Brief Pain Inventory (BPI) 中有關 Pain Interference 的部分共有 9 個 item, 包括 general activity, mood, walking ability, lifting heavy object, normal work (both housework and work outside the home), relation with other people, language processing, sleep 及 enjoyment of life","以上皆正確"],"officialAnswer":"C","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：Chap20 + Fig 41.3","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":6,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-21","year":110,"number":21,"topic":"未分類","text":"下列有關進行 Diagnostic block 預期 Diagnostic confidence 之 specificity and sensitivity 計算 公式，下列選項何者是錯誤？","options":["posttest odds = pretest odds × positive likelihood ratio","positive likelihood ratio = sensitivity / (1 − specificity)","pretest odds = prevalence / (1 − prevalence)","diagnostic confidence = [(posttest odds) / (1 −posttest odds)] × 100%","若 specificity 是 65%, 以及 prevalence 是 40%, 則 diagnostic confidence of positive comparative blocks 大約是 66%"],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處： P4900, P4902","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":7,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-22","year":110,"number":22,"topic":"未分類","text":"下列有關 Painful neuropathy 的敘述何者錯誤？","options":["Fabry disease 雖然以 neuropathic pain 為主要症狀, 但仍有全身性的影響包括心臟與腎臟","Inherited erythromelagia 的成因與鈉離子通道的變異有關","Postherpetic neuralgia 是因為 spinal cord dorsal horn neuron 內 dormant 的 Varicella-zoster virus reactivation 造成神經元破壞而產生","抗癌化學治療藥物, 例如 cisplatin 或 vincristine 可能會造成 painful neuropathy","Alcoholic neuropathy 未必與 thiamine 或其他維生素 B 群 deficiency 相關"],"officialAnswer":"C","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：Chap 24","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":7,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-23","year":110,"number":23,"topic":"未分類","text":"疼痛科醫師在面對非癌症患者需要開立 strong opioids 時，常會擔心成癮、濫用等問題。曾 有研究建議以 Five As of treatment success 來評估治療成效，以下何者非為 Five As 之一？","options":["Analgesia or pain score","Acceptance of interventional treatment","Adverse events","Aberrant behavior","Adherence to the treatment plan"],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"(P.1728 Table 108.1)","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":7,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-24","year":110,"number":24,"topic":"未分類","text":"生氣(Anger)等情緒反應在慢性疼痛病人當中可能較為頻繁出現，下列何者並非評估 Anger 的量表？","options":["State-trait anger expression inventory (STAXI-2)","Short form 36 (SF-36)","Targets and reasons for anger in pain sufferes (TRAPS)","Multi-dimensional anger inventory (MAI)",""],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"Anger disorders scale (ADS) 考題出處：Table 83.3","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":7,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-25","year":110,"number":25,"topic":"未分類","text":"Effects on postoperative morbidity of regional anaesthetic or analgesic techniques compared with those of general anaesthesia and systemic postoperative analgesics may reduce the following complications, except:","options":["pulmonary embloism","myocardial complications","pulmonary infectious complications","cerebral complications","other thromboembloic complications"],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：McMahon: Wall and Melzack's Textbook of Pain, 5th ed “Chapter 42 - Postoperative pain and its management”","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":8,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-26","year":110,"number":26,"topic":"未分類","text":"A 52-year-old man complains of a sudden onset of severe, stabbing pain in the left jaw and cheek that subsides in less than a minute. He is pain-free during the intervals between attacks. Activities such as combing his hair and shaving can cause the onset of this facial pain. He is otherwise healthy. The most likely diagnosis is","options":["trigeminal neuralgia","atypical facial pain","postherpetic neuralgia","vascular facial pain",""],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":8,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-27","year":110,"number":27,"topic":"未分類","text":"下列何者非為催眠(Hypnosis)在疼痛醫學中可能的應用範圍？","options":["Cancer pain management","Perioperative anxiolysis","Chronic low back pain","Local anesthetic systemic toxicity","Headache"],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"出處：table 86.1. 其實這題只要知道什麼是 local anesthetic systemic toxicity 就好了，而且這對 做介入治療的醫師非常重要。","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":8,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-28","year":110,"number":28,"topic":"未分類","text":"In neuropathic pain, the hyperexcitability demonstrated by wide-dynamic range cells in the dorsal horns seems to be related to increase basal release of excitatory amino acids, such as","options":["Dopamine","Glutamate","Acetylcholine","GABA","Norepinephrine"],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":9,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-29","year":110,"number":29,"topic":"未分類","text":"關於癌症相關的骨頭疼痛，下列敘述何者不適當","options":["癌症骨轉移最常見的位置是脊椎骨，一旦發現有骨轉移後，對於病患的產生癌症相關 併發症和存活時間會有明顯的改變","在動物癌症骨轉移模型，無論是 osteolytic 或是 osteoblastic model，都可以看到骨頭有 destructive injury。","過去研究發現 periosteum(骨膜)有豐富的交感與感覺神經纖維，另外 bone marrow 和 mineralized bone 也是有交感與感覺神經纖維分布，所以 bone pain 也就是 neuropathic pain。","Cyclooxygenase (COX)-2-specific inhibitors 對於 bone pain 病患的使用上是比 nonselective NSAIDs 安全，此外抑制 COX-2 也可以抑制 tumor burden，osteoclastogenesis，以及 bone destruction。","Intravenous zoledronic acid 已被證實對於 solid tumor 病患，可以降低骨骼相關併發症。"],"officialAnswer":"C","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"neuropathic pain 可能是 bone pain 的一種表現，造成 bone pain 有許多機制 考題出處：Ch. 46, p.2383, p2384-2386, p.2389, p.2390-2391","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":9,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-30","year":110,"number":30,"topic":"未分類","text":"Pain disorder may result in the sleep problem, and which of the sleep pattern is not often seen in patients:","options":["acute pain following surgical procedures is associated with reduced and fragmented sleep","acute postsurgical pain may result in diminished amounts of slow wave and rapid eye movement (REM) sleep","patients with chronic pain may suffered from reduced sleep efficiency and altered sleep architecture (increased wakefulness and stage 1 non-REM sleep)","subjects subjected to noxious stimuli during all stages of sleep will demonstrate a sleep awakening response and a moderate level of cortical arousal.","all of the above are common found in pain patients"],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":9,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-31","year":110,"number":31,"topic":"未分類","text":"epidural steroid injection 治療邏輯是針對椎間盤 nucleus pulposus 所釋放的發炎物質，下列 數種發炎物質 何者與椎間盤突出最沒有直接相關性？","options":["phospholipase A2","caspase","interleukins ( 1α, 1β, 6)","tumor necrosis factor","nitric oxide"],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：P4924","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":10,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-32","year":110,"number":32,"topic":"未分類","text":"The innervation of deep somatic tissue like muscle and joint is quite complex. Which of the following description is not appropriate?","options":["The nociceptors are predominantly activated by non-physiological stimuli which may cause damage to the structures (e.g. overload, twisting, strong pressure, ischemic contraction).","During inflammation or after trauma, nociceptors of joint and muscle show pronounced sensitization, in particular for mechanical stimuli.","Descending inhibition is enhanced during chronic inflammation but seems to be normalized during acute inflammation.","Both primary afferent fibers as well as sympathetic reflexes may aggravate inflammatory lesions.","Reduced release of hormones from the hypothalamic-pituitary-adrenal (HPA) axis such as cortisol, adrenal androgens and testosterone may cause a relative loss of anti-inflammatory activity."],"officialAnswer":"C","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處： P.621","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":10,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-33","year":110,"number":33,"topic":"未分類","text":"關於頭頸癌症病人的的敘述，下列何者不恰當？","options":["頭頸癌病人的疼痛問題，可能是腫瘤本身、化學治療、放射治療、或是手術造成的","粘膜炎(mucositis)的疼痛機制可能是黏膜產生潰瘍，暴露出神經末梢，使得黏膜表面變 得對疼痛敏感。","可以用來處置粘膜炎(mucositis)產生的疼痛，包括 topical benzydamine、乳狀鎂(milk of magnesia)、口服 acetaminophen, NSAIDs，甚至是嗎啡類藥物。","住院的癌症病患如果有嚴重的粘膜炎(mucositis)，可以考慮使用 Intravenous Patient-controlled analgesia (IVPCA) with morphine。","粘膜炎(mucositis)在頭頸癌病人很常發生，常會造成疼痛問題，是無法預防的 p."],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"可以預防，Table 45.4 (p.2363) 考題出處：Ch. 45 P.2348-2352、P.2353, P.2362-2363, P.2365-2367","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":10,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-34","year":110,"number":34,"topic":"未分類","text":"Choice a right description about treatment of cancer pain.","options":["Because of the complexity of cancer pain, 3 analgesic ladder from WHO was not useful.","Surgery, Chemotherapy and radiotherapy are not the analgesic titration for cancer pain.","Only 10-20% of patients ultimately require regular strong opioids.","Constipation is common for opioid use, but laxative can be used only when symptom exists.","None of above is right"],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：P1142-1144","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":11,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-35","year":110,"number":35,"topic":"未分類","text":"About the intrathecal drug delivery system, which of the following statements is NOT correct?","options":["It places medication directly into the cerebrospinal fluid that surrounds the spinal cord.","Morphine delivered directly to the intrathecal space is particularly effective because it does no have to circulate systemically to reach the CSF and the dorsal horn of the spinal cord.","As a result, much smaller doses are needed (e.g., approximately 1/30 of an oral morphine dose), and the frequency of side effects is reduced.","Advantages of intrathecal therapy in pain includes effective pain relief, reduced side effects for patients, reduced consumption of systemic medication, improved ability to perform ADLs, and enhanced quality of life.",""],"officialAnswer":"C","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":11,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-36","year":110,"number":36,"topic":"未分類","text":"A patient suffered from chronic low back pain with radiating to buttock, poster lateral thigh and lateral aspect of lower leg. Muscle weakness was observed in the extensor hallucis longus and tibialis anterior. Which lumbosacral root compression is the most likely？","options":["L2 root compression","L3 root compression","L4 root compression","L5 root compression","S1 root compression"],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":11,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-37","year":110,"number":37,"topic":"未分類","text":"Which of the followings clinical indicators with its suspected pathology for spinal pain is suggested to receive X-ray for first line test?","options":["fracture due to severe trauma","aortic aneurysm with cardiovascular risk factors","weight loss due to tumor","susecpted infection with fever, sweating","x-ray is not a first line test for the above causes of spinal pain"],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處： page 3877-3878, table 72.2. , Chapter 72. Acute low back pain","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":12,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-38","year":110,"number":38,"topic":"未分類","text":"關於｢The principles of pharmacotherapy endorsed by WHO｣，下列敘述何者不適當?","options":["五大原則: by the mouth, by the clock, by the ladder, for the individual, and with attention to detail。","Cancer pain 病患盡可能以口服止痛藥物為主，但如果病患有 dysphagia, uncontrolled vomiting, or GI obstruction 可以考慮改用其他途徑給予止痛藥物。","By the clock 的用意在於止痛藥物是”around-the-clock”的方式給予，讓大多數癌症病患 不再使用快速作用(immediate or rapid-onset)的嗎啡類止痛藥物。","沒有標準的嗎啡藥物使用劑量，理想的正確劑量是可以緩解病人疼痛，又能有最少的 副作用。","癌症疼痛病患的處方，是需要定期追蹤服藥順從性、藥物止痛效果、身體功能、副作用、 或是有無服藥後異常行為。"],"officialAnswer":"C","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"By the clock 的用意在於止痛藥物是”around-the-clock”的方式給予，主要是讓病患 baseline pain 可以得到控制，許多病患仍需要 immediate or rapid-onset 的嗎啡類止痛藥物，來緩解 breakthrough pain 考題出處：Ch. 43, P.2189-2191","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":12,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-39","year":110,"number":39,"topic":"未分類","text":"Which one of the following statement about the pathophysiology of herpes zoster is wrong?","options":["Herpes zoster most commonly manifests in the distribution of a single dorsal sensory or cranial nerve ganglion.","Why the reactivation of virus occurs in one ganglion when latent virus is present throughout the patient’s sensory ganglia is clear.","Declining cellular immunity is a major risk factor for reactivation of the virus, which is thought to occur when cell-mediated immunity falls below a critical level.","This impression is supported by evidence that even individuals with adequate levels of serum antibodies to varicella-zoster virus (VZV) antigen can, over time, exhibit T cells with reduced ability to proliferate and defend against VZV infections.","Cell-mediated immunity appears to play a crucial role in preventing reactivation of latent VZV."],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：Bonica's Management of Pain, 5e, p. 375.","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":12,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-40","year":110,"number":40,"topic":"未分類","text":"Which of the following is the acceptable statement about neurodestructive RF lesions?","options":["These temperatures are resulted from friction heat.","The size of RF lesion with 22 gauge RF needle is around with a radius of 5 mm","The heat is generated on the tip of RF needle. The RF needle then heat up the tissues.","The RF pe 口 nanent neurodestructive lesion is formed when neural temperatures exceed 42 C","All of the above"],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":13,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-41","year":110,"number":41,"topic":"未分類","text":"Which of the following drug is categorized as Agonist-Antagonist and should \"Not\" be used in opioid tolerant patients.","options":["Morphine","Tramadol","Nalbuphine","Hydromorphone","Methadone"],"officialAnswer":"C","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"Chap 31","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":13,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-42","year":110,"number":42,"topic":"未分類","text":"關於 breakthrough pain (BTP)，下列敘述何者不適當","options":["BTP 的原因與發生的部位就是 baseline persistent pain 相同。","BTP 可以是可預期，或是特定動作或生理反應而產生。","在給予定時止痛藥物之後發生的 BTP，有可能是給予藥物的間距時間過長，通常這樣的 BTP 是可以預期，而且會在固定的期間發生。","發生 BTP 的時間可能是無法預期，跟特定動作或時間無關。","典型的 BTP 通常在 3-5 分鐘發生，持續約 30 分鐘，每次發生的強度不一定相同。"],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"P.2080: BTP refers to sudden increases in the base level of pain or different but recurring pains. P.2080: The cause and anatomical site of BTP is often, but not always, the same as that of the baseline persistent pain 考題出處：Ch. 42: P. 2080","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":13,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-43","year":110,"number":43,"topic":"未分類","text":"Which of following description about opioid receptors is \"Incorrect\" ?","options":["Opioid receptors belong to the superfamily of G protein–coupled receptors (GPCR)","Opioid receptors are coupled to Gs protein to trigger downstream signaling.","Overall opioid receptor activation leads to inhibit neuronal activity","In spinal cord level, opioid receptors are located mostly in the superficial dorsal horn","Endogenous opiates maybe released by immune cells and work on both central and peripheral opioid receptors."],"officialAnswer":"B","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"Chap 30","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":14,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-44","year":110,"number":44,"topic":"未分類","text":"Which of following description about non-steroidal anti-inflammatory drugs (NSAIDs) pharmacology is \"Correct\"?","options":["NSAIDs work by inhibiting the inflammation associated enzyme cyclooxygenase and lipoxygenase","Perioperative use of NSAIDs will not increase the risk of surgical site bleeding","NSAIDs will not have drug-drug interaction with anticoagulant (such as warfarin)","Cyclooxygenase-2 (Cox-2) is the inducible isoform of cyclooxygenase but is constitutively expressed in certain tissues such as brain and kidney","Compared with non-selective NSAIDs, long term use of Cox-2 inhibitors will significantly reduce the risk of serious cardiovascular events, renal failure or congestive heart failure."],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"Chap: 33","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":14,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-45","year":110,"number":45,"topic":"未分類","text":"Which of following description about using anticonvulsants (used as Analgesic Drugs is \"Correct\"?","options":["Most commonly used anticonvulsants as analgesics appear to work through potentiation of voltage-gated sodium and calcium channels","Sodium channel subtype 1.4 &1.5 are highly expressed in neuronal cell and could be the drug target for anticonvulsant medication","Gabapentinoid (Gabapentin & Pregabalin) works on GABA receptor","Topiramate works only on voltage-gated sodium channel","Lamotrigine and Phenytoin work on voltage-gated sodium channels"],"officialAnswer":"E","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"Chap 35&36","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":14,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-46","year":110,"number":46,"topic":"未分類","text":"Which of the folllowing medication has a greater and long term effect for palliation of pain than placebo in treating chronic low back pain?","options":["bezodiazepaine","antidepressants","pregabalin","opioids","none of the above medications can offter a greater and lon-term analgesic effect"],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：page 3935-3926, Chapter 73. Chronic low back pain","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":15,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-47","year":110,"number":47,"topic":"未分類","text":"Which of following description about \"antidepressant analgesic\" is \"Correct\"?","options":["In terms of treatment efficacy (smaller number needed to treat NNT), pregabalin is much better than tricyclic antidepressant and listed as first line therapy for neuropathic pain","In terms of treatment efficacy (smaller number needed to treat NNT), SSRI is better than SNRI for common neuropathic pain such as postherpetic neuralgia or painful diabetic polyneuropathy","Venlafaxine is effective for treatment of neuropathic pain associated with beast cancer.","For painful diabetic neuropathy, comparison of amitriptyline and pregabalin showed no difference in pain relief but fewer adverse effects with pregabalin.","All of above"],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"Chap 34","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":15,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-48","year":110,"number":48,"topic":"未分類","text":"Which one of the following statement about central pain is wrong?","options":["Central pain involves plasticity in a single area of CNS.","Sensitization of the CNS plays a major role in central pain and involves neuronal hyper-excitability resulting in an increased response to synaptic inputs, decreased threshold, expansion of receptive fields, and access of low-threshold Aβ mechanoreceptors to pain pathways.","The clinical consequences of central pain are allodynia, hyperalgesia, and after-sensations.","Central sensitization may also include spontaneous discharges.","Spontaneous discharges in damaged pain pathways or deafferented rostral neurons may be responsible for spontaneous ongoing or intermittent pain."],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：Bonica's Management of Pain, 5e, p. 399.","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":15,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-49","year":110,"number":49,"topic":"未分類","text":"Which of the following diagnosis due to failed back surgery is not able to get evident diagnostic support from MRI?","options":["lateral canal stenosis","painful disk","recurrent herniated nucleus pulposus","SI joint pain","MRI can help differential diagnois of all of the above causes of failed back surgery."],"officialAnswer":"D","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處： page 3993, table 75.3. , Chapter 75. Failed back surgery syndrome","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":15,"parseWarning":[],"importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"},{"id":"official-110-50","year":110,"number":50,"topic":"未分類","text":"見下圖，不同的傷害性刺激 (熱、酸或化學性、機械性刺激、冷) 所興奮的表皮傷害性接 受器 (1, 2, 3, 4)，可對應左側四組 A, B, C, D，按 1, 2, 3, 4 正確排列依序為：","options":["A, B, C, D","A, C, B, D","B, C, A, D","C, B, D, A","D, C, B, A"],"officialAnswer":"A","verifiedAnswer":null,"verified":"pending","explanation":"","officialNote":"考題出處：Bonica's Management of Pain Fifth Edition; Chap 2, page 272, Figure 3.1-B;","sources":[{"title":"110 年學會原始考題","url":"https://pain.org.tw/index.php/exam_page/index/6/1"}],"origin":"official","sourceFile":"110.pdf","page":16,"parseWarning":[],"imageData":"data:image/png;base64,","imageAlt":"第 110 年第 50 題原始示意圖，傷害感受器刺激與受體配對","importQC":"人工需再確認完整原題；官方答案未經逐題醫學查證"}]);
